-- Lecture seule. Liste figee des68 sessions reçues ; aucune jointure.
SELECT b.*
FROM prod_cotton_global_0.general_branding b
WHERE b.id_type_branding = 1
  AND b.id_related IN (
      29370, 29371, 29622, 29623, 29631, 29632, 29643, 29644, 29668, 29669,
      29670, 29673, 29674, 29705, 29706, 29756, 29774, 29775, 29827, 29828,
      29829, 29830, 29831, 29832, 29833, 29834, 29835, 29836, 29837, 29838,
      29839, 29840, 29913, 29914, 29915, 29916, 29976, 29978, 29979, 30029,
      30030, 30031, 30035, 30036, 30047, 30049, 30053, 30054, 30055, 30056,
      30057, 30058, 30059, 30060, 30061, 30062, 30063, 30064, 30065, 30066,
      30067, 30068, 30069, 30071, 30121, 30122, 30126, 30127
  )
ORDER BY b.id_related, b.id;
